// Builds dist/worker/mcp-remote.worker.js: src/api.ts and src/remote.ts compiled by tsc, joined into one
// self-contained block with no imports, wrapped in an IIFE so its names cannot collide with a Worker file
// it is pasted into. Run after `npm run build`. Output exposes: const MCP_REMOTE = { handleMcpRequest, ApiError, TOOLS, ... }.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const strip = (s) =>
  s
    .replace(/^import\s[^;]*;\s*$/gm, "")
    .replace(/^\/\/# sourceMappingURL=.*$/gm, "")
    .replace(/^export\s+\{[^}]*\};?\s*$/gm, "")
    .replace(/^export\s+(?=(const|let|class|function|async function)\b)/gm, "");

const api = strip(readFileSync(join(root, "dist/src/api.js"), "utf8"));
const remote = strip(readFileSync(join(root, "dist/src/remote.js"), "utf8"));
const out =
  "// receipts-index-mcp remote module, generated by mcp/scripts/build-worker-module.mjs. Do not edit by hand.\n" +
  "const MCP_REMOTE = (() => {\n" +
  api + "\n" + remote + "\n" +
  "return { handleMcpRequest, ApiError, TOOLS, SUPPORTED_PROTOCOL_VERSIONS, REMOTE_SERVER_VERSION };\n" +
  "})();\n";
if (/^\s*(import|export)\s/m.test(out)) throw new Error("import or export left in generated module");
mkdirSync(join(root, "dist/worker"), { recursive: true });
writeFileSync(join(root, "dist/worker/mcp-remote.worker.js"), out);
console.log("wrote dist/worker/mcp-remote.worker.js (" + out.length + " chars)");
